تحدت الجهة وتُطرحان إذا تعاكستا.", "M": ["أرسم القوتين من نفس المبدأ", "أنشئ متوازي الأضلاع", "أقيس طويلة القطر وأحولها إلى نيوتن بالسلّم"], "X": "المحصلة قوة واحدة تعطي نفس الأثر الذي تعطيه القوتان معا. في حالتين خاصتين يكفي الجمع أو الطرح.", "EX": [["`→F_{1}` و`→F_{2}` لهما نفس الجهة ونفس المبدأ، شدتاهما 12 N و6 N. ما محصلتهما؟", "نفس الجهة: `R = 12 + 6 = 18 N` ولها نفس الجهة والمنحى"], ["نفس السؤال إذا كانتا متعاكستين في الجهة وفي المبدأ نفسه.", "متعاكستان: `R = 12 - 6 = 6 N` وجهتها جهة القوة الأكبر (12 N)"], ["`→F_{1}` و`→F_{2}` لهما المبدأ نفسه، شدتاهما 4 N و6 N وبينهما زاوية 30°. أوجد المحصلة بيانيا.", "نختار السلّم `1 cm ↔ 1 N`. نرسم القوتين بينهما 30° ثم نكمل متوازي الأضلاع. المحصلة هي قطره من المبدأ، وطوله حوالي 9,7 cm. إذن `R ≈ 9,7 N`"]]}, {"n": 10, "m": 1, "i": "📐", "t": "تحليل قوة إلى مركبتين", "B": [["المعنى", ["نحلل شعاع القوة إلى مركبتين على حاملين يشكلان معلما متعامدا ومتجانسا"]], ["المركبتان", ["القوة الأصلية هي محصلة المركبتين `→F = →F_{x} + →F_{y}`"]], ["مثال: مستوٍ مائل", ["نحلل ثقل الجسم `→P` إلى `→P_{x}` (موازية للمستوي) و`→P_{y}` (عمودية عليه)"]], ["العلاقة", ["`P_{x} = P × sin α` و`P_{y} = P × cos α` (α زاوية ميل المستوي)"]]], "K": "تحليل القوة عكس التركيب: نستبدل القوة بمركبتين متعامدتين مجموعهما يساوي القوة الأصلية.", "M": ["أختار محورين مناسبين", "أرسم متوازي أضلاع (مستطيل) قطره القوة", "أقرأ المركبتين من الرسم"], "X": "نفكك قوة واحدة مائلة إلى قوتين: واحدة على كل محور، فيسهل علينا دراسة التوازن على كل محور على حدة.", "EX": [["جسم كتلته 1,5 kg على مستوٍ مائل بزاوية 30° وخيط يشدّه. احسب ثقله ومركبته الموازية للمستوي (`g = 9,81`).", "`P = 1,5 × 9,81 = 14,7 N`. `P_{x} = P × sin 30° = 14,7 × 0,5 ≈ 7,4 N`"], ["في التجربة السابقة قيس توتر الخيط `T = 5,0 N`. هل يوجد احتكاك؟ علّل.", "لو لم يوجد احتكاك لكان `T = P_{x} ≈ 7,4 N` عند التوازن. لكن `T = 5,0 N` أصغر، فالفرق حوالي 2,4 N يعوّضه احتكاك المستوي. إذن يوجد احتكاك"]]}, {"n": 11, "m": 1, "i": "🌊", "t": "دافعة أرخميدس وخصائصها", "B": [["التعريف", ["قوة تلامسية موزعة يؤثر بها سائل على جسم مغمور فيه جزئيا أو كليا", "لا يذوب فيه ولا يتفاعل معه"]], ["الرمز", ["`→F_{A}` ووحدتها النيوتن N"]], ["نقطة التأثير والمنحى", ["نقطة التأثير: المركز الهندسي للجزء المغمور (مركز ثقل السائل المزاح)", "المنحى شاقولي"]], ["الجهة والشدة", ["الجهة: من الأسفل نحو الأعلى", "الشدة: تساوي ثقل السائل المزاح"]]], "K": "دافعة أرخميدس قوة شاقولية نحو الأعلى، شدتها تساوي ثقل السائل المزاح.", "M": ["أحدد الجزء المغمور", "أرسم الدافعة من مركزه نحو الأعلى", "أقارنها بالثقل"], "X": "السائل يدفع الجسم المغمور نحو الأعلى، ولهذا يبدو الجسم أخف داخل الماء.", "EX": [["قطعة خشب في الماء تطفو. ما القوى المؤثرة عليها وما اتجاهها؟", "القوتان: ثقل القطعة `→P` (شاقولي نحو الأسفل) ودافعة أرخميدس `→F_{A}` (شاقولية نحو الأعلى). عند الطفو متساويتان في الشدة"], ["أين تنطبق نقطة تأثير دافعة أرخميدس على كرة مغمورة كليا؟", "على المركز الهندسي للكرة (مركز الجزء المغمور وهو الكرة كلها)"]]}, {"n": 12, "m": 1, "i": "🧲", "t": "قياس شدة دافعة أرخميدس: الثقل الظاهري", "B": [["الثقل الحقيقي P", ["ثقل الجسم وهو غير مغمور (معلّق بالربيعة)"]], ["الثقل الظاهري P'", ["القيمة التي تشير إليها الربيعة والجسم مغمور في السائل"]], ["النتيجة", ["P' أصغر من P: نقصان القيمة دليل على قوة نحو الأعلى هي دافعة أرخميدس"]], ["العلاقة", ["`F_{A} = P - P'`"]]], "K": "F_A = P − P′: شدة الدافعة تساوي الفرق بين الثقل الحقيقي والثقل الظاهري.", "M": ["أقرأ P والجسم في الهواء", "أقرأ P' والجسم مغمور", "أحسب الفرق"], "X": "عندما نغمر الجسم تنقص قراءة الربيعة، ونقصان القراءة هو بالضبط شدة دافعة أرخميدس.", "EX": [["جسم ثقله في الهواء 4,41 N. عند غمره كليا في الماء تشير الربيعة إلى 2,78 N. احسب شدة دافعة أرخميدس.", "`F_{A} = P - P' = 4,41 - 2,78 = 1,63 N`"], ["لماذا يكون الثقل الظاهري أصغر من الثقل الحقيقي؟", "لأن الدافعة (نحو الأعلى) تنقص من القوة التي تشدّ الربيعة نحو الأسفل: `P' = P - F_{A}`"]]}, {"n": 13, "m": 1, "i": "🧮", "t": "حساب الدافعة: ثقل السائل المزاح", "B": [["السائل المزاح", ["عند غمر جسم في سائل يزيح حجما V من السائل مساويا لحجمه المغمور"]], ["العلاقة", ["`F_{A} = P_{l}` (ثقل السائل المزاح)", "`P_{l} = m_{l} × g` و`m_{l} = ρ_{l} × V_{l}`"]], ["القانون", ["`F_{A} = ρ_{l} × V_{l} × g`"]], ["الوحدات", ["ρ بـ kg/m³، V بـ m³، g بـ N/kg، والدافعة بـ N", "`1 L = 10^{-3} m^{3}` و`1 dm^{3} = 1 L`"]]], "K": "F_A = ρ × V × g: الكتلة الحجمية للسائل × حجمه المزاح × الجاذبية.", "M": ["أحوّل الحجم إلى m³", "أستعمل كتلة السائل الحجمية (الماء 1000 kg/m³)", "أطبق `F_{A} = ρ × V × g`"], "X": "الدافعة تساوي وزن الماء الذي أزاحه الجسم، فكلما كان الجسم أكبر حجما أو السائل أكثف زادت الدافعة.", "EX": [["قطعة معدنية كتلتها 450 g وحجمها 0,167 dm³ معلقة بربيعة ومغمورة كليا في الماء. احسب شدة الدافعة والثقل الظاهري (`ρ = 1000 kg/m³` و`g = 9,81`).", "`V = 0,167 dm^{3} = 1,67×10^{-4} m^{3}`. `F_{A} = 1000 × 1,67×10^{-4} × 9,81 ≈ 1,64 N`. `P = 0,45 × 9,81 ≈ 4,41 N`. `P' = P - F_{A} ≈ 2,78 N`"], ["سبيكة معدنية متجانسة ثقلها في الهواء 380 N ومغمورة كليا في الماء 320 N. احسب حجمها وكتلتها الحجمية.", "`F_{A} = 380 - 320 = 60 N`. `V = F_{A}/(ρ × g) = 60/(1000 × 9,81) ≈ 6,12×10^{-3} m^{3} = 6,12 L`. `m = P/g = 380/9,81 ≈ 38,7 kg`. `ρ = m/V ≈ 6333 kg/m^{3}`"], ["مكعب ثقله 310 N يصبح ثقله 210 N عند غمره كليا في كحول كتلته الحجمية 806 kg/m³. احسب F_A وحجمه وكتلته الحجمية.", "`F_{A} = 310 - 210 = 100 N`. `V = 100/(806 × 9,81) ≈ 1,265×10^{-2} m^{3} = 12,65 L`. `m = 310/9,81 ≈ 31,6 kg`. `ρ = m/V ≈ 2500 kg/m^{3}`"]]}, {"n": 14, "m": 1, "i": "🔬", "t": "العوامل المؤثرة في الدافعة", "B": [["كثافة السائل", ["كلما كان السائل أكثف زادت شدة الدافعة"]], ["حجم الجزء المغمور", ["كلما كبر الحجم المغمور زاد حجم السائل المزاح فتزداد الدافعة"]], ["لا تتأثر بـ", ["شكل الجسم", "كتلة الجسم وكثافة مادته", "عمق الغمر (ما دام مغمورا كليا)"]], ["تجارب", ["جسمان مختلفا الكثافة ومتساويا الحجم: نفس الدافعة", "حجمان مختلفان في نفس السائل: دافعتان مختلفتان"]]], "K": "الدافعة تتعلق بكثافة السائل وبحجم الجزء المغمور فقط.", "M": ["أقارن السوائل المستعملة", "أقارن حجمي الجسمين", "أتجاهل الكتلة والشكل"], "X": "القانون F = ρ·V·g فيه ρ السائل وV المغمور فقط، ولا يدخل فيه شيء من مادة الجسم.", "EX": [["جسمان من الحديد والخشب لهما نفس الحجم مغموران كليا في الماء. أيهما دافع