], ["المأخذ الأرضي", ["ثلاثة مرابط: الطور والحيادي والأرض"]], ["الطور", ["سلك بغلاف أحمر أو بني، موصّل بتيار ذي توتر 220 V", "يسبب الصدمة عند لمسه وحده أو مع الحيادي"]], ["الحيادي والأرضي", ["الحيادي: غلاف أزرق، غير موصّل بتيار", "الأرضي: غلاف أصفر وأخضر، موصّل بالأرض"]]], "K": "الطور (أحمر/بني) خطير، الحيادي (أزرق)، الأرضي (أصفر وأخضر) يحمي من الصعق.", "M": ["أميز الأسلاك بألوانها", "أستعمل مفك كاشف التيار للطور فقط", "لا ألمس الطور أبدا"], "X": "الطور هو السلك الحي: التوتر بينه وبين الحيادي (أو الأرض) حوالي 220 V، بينما التوتر بين الحيادي والأرض يساوي 0 V.", "EX": [["قيس التوتر بين المرابط الثلاثة A وB وC لمأخذ: بين A وB يساوي 230 V، وبين A وC يساوي 0 V، وبين B وC يساوي 230 V. عيّن كل مربط.", "التوتر بين A وC يساوي 0 V فهما الحيادي والأرضي. التوتر بين B وكل من A وC يساوي 230 V فـ B هو الطور"], ["لماذا يضيء مصباح مفك كاشف التيار عند لمس الطور فقط؟", "لأن الطور موصّل بتيار كهربائي ذي توتر عال، فتمرّ شدة صغيرة عبر المفك فيضيء. أما الحيادي فلا يغذي المصباح"]]}, {"n": 28, "m": 2, "i": "⚠️", "t": "أخطار التيار الكهربائي", "B": [["عيوب العزل", ["ارتفاع حرارة الأسلاك وانصهار المادة العازلة وتعرّيها", "فتحدث ملامسة الطور والحيادي (استقصار) أو ملامسة الطور للهيكل المعدني"]], ["زيادة الشدة والحمولة", ["تشغيل عدة أجهزة معا (غسالة، مكيف، تلفاز...) يرفع شدة التيار فوق القيمة المقبولة", "يسبب قطع القاطع أو تلف الأجهزة أو حريقا"]], ["الصدمة الكهربائية", ["الجسم يصبح جزءا من دارة مغلقة والجلد الرطب ناقل جيد", "توتر متناوب أكبر من 25 V في ظروف رطبة قد يكون مميتا"]], ["النتائج", ["حوادث مميتة: تيار متناوب بشدة 40 mA يسبب صعقة قاتلة", "حرائق وتلف الأجهزة"]]], "K": "أخطار التيار: الاستقصار، زيادة الشدة والحمولة، والصعق الكهربائي بملامسة الطور.", "M": ["أتجنب الأسلاك العارية", "لا أشغل عدة أجهزة قوية على مأخذ واحد", "أحافظ على جفاف اليدين"], "X": "الطائر على سلك كهربائي لا يتأذى لأنه يلمس خطا واحدا فلا تُغلق دارة عبر جسمه، لكنه إذا لمس سلكين معا أُغلقت الدارة فمات.", "EX": [["شخص مقاومة جسمه 1000 Ω. ما أكبر توتر يتعرض له دون خطر إذا كان لا يتحمل شدة أكبر من 50 mA؟", "`U = R × I = 1000 × 0,05 = 50 V`"], ["عامل صيانة تعرض لتوتر قيمته العظمى 532 V ومقاومة جسمه 1200 Ω. ما القيمة العظمى للشدة بالمللي أمبير؟", "`I_{max} = U_{max}/R = 532/1200 ≈ 0,443 A ≈ 443 mA`. وهي أكبر بكثير من 40 mA (حد الخطر) فالصعق مميت"]]}, {"n": 29, "m": 2, "i": "🛡️", "t": "وسائل الأمن: التأريض والمنصهرة", "B": [["التوصيل الأرضي", ["نقل التيار المتسرب من الشبكة إلى الأرض لحماية الأشخاص من الصعق"]], ["المنصهرة", ["سلك ينصهر إذا تجاوزت الشدة الحد المسجل عليها فتفتح الدارة"]], ["تركيبها", ["دائما على سلك الطور"]], ["القاطعة", ["تركّب على الطور دائما لتفادي الصعق عند تغيير المصابيح"]]], "K": "التأريض يحمي الأشخاص، والمنصهرة تحمي الدارة من زيادة الشدة، وكلاهما على الطور.", "M": ["أركّب القاطعة والمنصهرة على الطور", "أوصل الأجهزة المعدنية بالأرض", "أستعمل منصهرة مناسبة للشدة"], "X": "الهيكل المعدني المؤرَّض يوصل أي تسرّب كهربائي إلى الأرض بدل أن يمر عبر جسم الإنسان.", "EX": [["لماذا نركّب المنصهرة والقاطعة على سلك الطور؟", "لأن الطور هو السلك الحي: قطعه بالمنصهرة أو القاطعة يعزل الجهاز عن التيار ويحمي الأشخاص عند التدخل"], ["ما دور سلك التأريض في غسالة هيكلها معدني؟", "إذا لامس الطور الهيكل المعدني انتقل التيار إلى الأرض بسلك التأريض فلا تحدث صعقة عند لمس الغسالة"]]}, {"n": 30, "m": 2, "i": "🔒", "t": "القواطع الكهربائية", "B": [["القاطع الرئيسي", ["يركّب بعد العدّاد، حساسيته حوالي 500 mA عادة", "يفصل تلقائيا عند تجاوز الحد وعند خلل خارج الشبكة"]], ["القاطع التفاضلي", ["يقارن شدة التيار في الطور والحيادي", "إذا اختلفتا (تسرب إلى الأرض) فصل التيار آليا", "حساسيته عادة 30 mA"]], ["القاطع التقسيمي (الجزئي)", ["يحمي دارة واحدة من الشدة الزائدة عن الحد", "وقد حل محل المنصهرة في التركيبات الحديثة"]], ["اللوح الكهربائي", ["العناصر الأساسية: القواطع التفاضلية والتقسيمية والمنصهرات"]]], "K": "القاطع التفاضلي (30 mA) يحمي الأشخاص من الصعق، والتقسيمي يحمي كل دارة من زيادة الشدة.", "M": ["التفاضلي لتسرب التيار إلى الأرض", "التقسيمي لزيادة الحمولة", "الرئيسي بعد العدّاد"], "X": "القاطع التفاضلي يعمل كحارس: إن لاحظ أن ما يخرج من الطور لا يساوي ما يعود في الحيادي عرف أن جزءا ذهب إلى الأرض (عبر جسم شخص مثلا) فيقطع التيار.", "EX": [["قاطع تفاضلي حساسيته 30 mA. ماذا يحدث إذا تسرب تيار شدته 40 mA عبر شخص؟", "40 mA أكبر من 30 mA فيقطع القاطع التيار آليا فيحمي الشخص"], ["ما الفرق بين المنصهرة والقاطع التفاضلي؟", "المنصهرة تحمي الدارة من زيادة الشدة بانصهار سلكها (يجب استبدالها). التفاضلي يحمي الأشخاص بقطع التيار عند تسرب إلى الأرض ويعاد تشغيله"]]}, {"n": 31, "m": 2, "i": "🏠", "t": "قواعد الأمن في مخطط شبكة منزلية وحساب الحمولة", "B": [["التركيب", ["خط التوزيع إلى العدّاد: الحيادي موصول بالأرض", "يوصل الطور والحيادي بالعداد ثم بالقاطع التفاضلي"]], ["الخطوط", ["تنطلق خطوط التوزيع من التفاضلي مرورا بلوحة التوزيع", "كل خط محمي بمنصهرة أو قاطع تقسيمي على مربط الطور"]], ["الحمولة", ["`P = U × I` فـ `I = P / U`", "مجموع استطاعات الأجهزة المشغلة معا يحدد الشدة"]], ["التطبيق", ["عند تشغيل أجهزة معا نقارن الشدة المحسوبة بقيمة القاطع"]]], "K": "كل خط محمي على الطور بقاطع تقسيمي، والتفاضلي للحماية العامة، وشدة التيار تحسب من P = U × I.", "M": ["أجمع الاستطاعات", "أحسب `I = P/U`", "أقارن بقيمة المنصهرة أو القاطع"], "X": "الأجهزة القوية تسحب شدة كبيرة؛ فإذا شغلناها كلها معا قد تتجاوز الشدة قيمة القاطع فينقطع التيار.", "EX": [["مطبخ فيه أجهزة استطاعاتها 1200 W و850 W و2000 W و1500 W تعمل معا على 220 V وقاطع 20 A. هل يقطع القاطع التيار؟", "`P = 1200 + 850 + 2000 + 1500 = 5550 W`. `I = P/U = 5550/220 ≈ 25,2 A`. وهي أكبر من 20 A فيقطع القاطع التيار (زيادة الحمولة)"], ["غسالة استطاعتها 4,4 kW على 220 V موصولة بمنصهرة 10 A. هل يمكن تشغيلها بأمان؟", "`I = P/U = 4400/220 = 20 A`. وهي أكبر من 10 A فتنصهر المنصهرة. الحل: تغيير المنصهرة بأخرى مناسبة (أكبر من 20 A) وسلك أسمك وخط خاص بالغسالة"]]}, {"n": 32, "m": 3, "i": "💧", "t": "المحاليل المائية: جزيئية وشاردية", "B": [["المحلول المائي", ["محلول مذيبه الماء", "مثال: ماء + سكر، ماء + ملح الطعام"]], ["محلول جزيئي", ["مثل الماء السكري", "لا ينقل التيار الكهربائي", "السكر مركب جزيئي: عند انحلاله تتحرر جزيئات الغلوكوز C₆H₁₂O₆ وهي غير مشحونة"]], ["محلول شاردي", ["مثل محلول كلور الصوديوم", "ينقل التيار الكهربائي", "عند انحلال الملح تتحرر الشوارد Na⁺ و Cl⁻ وهي حاملات للشحنة"]], ["التجربة", ["نركب دارة فيها مولد ومصباح وأمبير متر ومسريان من الغرافيت", "في الماء المقطر وفي الماء السكري لا يمر التيار، وفي الماء المالح يمر ويتوهج المصباح"]]], "K": "المحلول الشاردي ينقل التيار الكهربائي بفضل الشوارد الحرة الحركة، أما المحلول الجزيئي فلا ينقله.", "M": ["محلول مائي مذيبه الماء", "مركب جزيئي ← محلول جزيئي ← لا ينقل التيار", "مركب شاردي ← محلول شاردي ← ينقل التيار", "الملح الصلب لا ينقل التيار لأن شواردته غير حرة الحركة"], "X": "الكهرباء في المحلول تنتقل بواسطة أجزاء مشحونة (الشوارد). السكر لا يعطي أجزاء مشحونة فلا يمر التيار، والملح يعطي شوارد فيمر التيار.", "EX": [["نضع في الماء ملح الطعام ثم سكرا. أي المحلولين ينقل التيار ولماذا؟", "محلول ملح الطعام ينقل التيار لأنه يحتوي على شوارد Na⁺ و Cl⁻ حرة الحركة. أما الماء السكري فلا ينقله لأنه يحتوي على جزيئات غلوكوز متعادلة كهربائيا"], ["لماذا لا ينقل الملح الصلب التيار الكهربائي؟", "لأن الشوارد في الحالة الصلبة ثابتة في أماكنها (ليست حرة الحركة)، وعند انحلاله في الماء تتحرر فتنقل التيار"]]}, {"n": 33, "m": 3, "i": "⚛️", "t": "الشاردة وأنواعها", "B": [["التعريف", ["الشاردة ذرة (أو مجموعة ذرات) مشحونة كهربائيا", "تنتج عن فقدان إلكترون أو أكثر أو اكتسابه"]], ["الشاردة الموجبة", ["ذرة فقدت إلكترونا أو أكثر", "مثال: شاردة الحديد الثنائي Fe²⁺", "`Fe → Fe^{2+} + 2e^{-}`"]], ["الشاردة السالبة", ["ذرة اكتسبت إلكترونا أو أكثر", "مثال: شاردة الأكسجين O²⁻", "`O + 2e^{-} → O^{2-}`"]], ["حسب التركيب", ["بسيطة: من ذرة واحدة مثل Na⁺ و Cl⁻", "مركّبة: من عدة ذرات مثل NH₄⁺ و SO₄²⁻"]], ["قراءة الرمز", ["الرقم والإشارة على أعلى رمز الذرة", "الرقم = عدد الإلكترونات المفقودة أو المكتسبة، والإشارة (+) أو (−) تدل على نوع الشحنة"]]], "K": "الشاردة ذرة أو مجموعة ذرات اكتسبت أو فقدت إلكترونات، فهي موجبة (فقدان) أو سالبة (اكتساب).", "M": ["فقدان إلكترونات ← شاردة موجبة (+)", "اكتساب إلكترونات ← شاردة سالبة (−)", "الذرة متعادلة، أما الشاردة فمشحونة", "الشاردة البسيطة من ذرة واحدة والمركبة من عدة ذرات"], "X": "الذرة فيها عدد من البروتونات (+) يساوي عدد الإلكترونات (−) فهي متعادلة. إذا خسرت إلكترونا يزيد (+) فتصير موجبة، وإذا ربحت إلكترونا يزيد (−) فتصير سالبة.", "EX": [["اكتب الشاردة الموجبة الناتجة عن كل من: Ag و Sn و Al و Mg و Zn.", "`Ag^{+}` ، `Sn^{2+}` ، `Al^{3+}` ، `Mg^{2+}` ، `Zn^{2+}`"], ["اكتب صيغة الشاردة المركبة لكل من: الكبريتات، النترات، الكربونات، الهيدروكسيد.", "الكبريتات `SO_{4}^{2-}` ، النترات `NO_{3}^{-}` ، الكربونات `CO_{3}^{2-}` ، الهيدروكسيد `OH^{-}`"], ["ذرة تحمل 11 بروتونا وفقدت إلكترونا واحدا. ما شحنتها وما رمزها؟", "عدد الإلكترونات 10 وعدد البروتونات 11 فالشحنة الإجمالية +1: شاردة موجبة، رمزها X⁺ (وهي Na⁺ لأن Z = 11)"], ["تحتوي شاردة الألومينات Al(OH)₄⁻ على كم ذرة وما نوعها وعدد الإلكترونات الزائدة؟", "تتكون من ذرة ألمنيوم واحدة و4 ذرات أكسجين و4 ذرات هيدروجين أي 9 ذرات. هي شاردة مركبة سالبة تحمل إلكترونا زائدا واحدا"]]}, {"n": 34, "m": 3, "i": "🧂", "t": "المركب الشاردي وصيغتاه", "B": [["التعريف", ["المركب الشاردي نوع كيميائي متعادل كهربائيا", "مكوّن من شوارد موجبة وسالبة مجموع شحناتها الموجبة يساوي مجموع شحناتها السالبة"]], ["الصيغة الإحصائية", ["تدل على المركب الشاردي في الحالة الصلبة", "مثال: NaCl و CuCl₂"]], ["الصيغة الشاردية", ["تدل على المركب وهو منحل في الماء", "مثال: (Na⁺ , Cl⁻) و (Cu²⁺ , 2Cl⁻)"]], ["كيف نكتبها؟", ["نكتب الشاردة الموجبة أولا ثم السالبة", "نضبط الأعداد حتى يتعادل المجموع"]]], "K": "المركب الشاردي متعادل: صيغته الإحصائية للصلب وصيغته الشاردية للمحلول.", "M": ["الصلب: صيغة إحصائية NaCl", "المنحل: صيغة شاردية (Na⁺ , Cl⁻)", "مجموع الشحنات الموجبة = مجموع الشحنات السالبة"], "X": "الملح لا يحمل شحنة إجمالية: كل شاردة موجبة يوازنها شاردة سالبة. لذلك CuCl₂ يحتوي شاردة Cu²⁺ واحدة مقابل شاردتي Cl⁻.", "EX": [["اكتب الصيغة الشاردية لكلور الحديد الثنائي FeCl₂ وكلور الألمنيوم AlCl₃.", "FeCl₂: (Fe²⁺ , 2Cl⁻) . AlCl₃: (Al³⁺ , 3Cl⁻). في كل منهما مجموع الشحنات صفر"], ["لماذا نكتب 2Cl⁻ في صيغة كلور النحاس الثنائي؟", "لأن شاردة Cu²⁺ تحمل شحنتين موجبتين، فنحتاج شاردتين Cl⁻ (كل واحدة بشحنة سالبة) لنحصل على التعادل: +2 − 2 = 0"]]}, {"n": 35, "m": 3, "i": "🧭", "t": "هجرة الشوارد", "B": [["التجربة", ["شريحة زجاجية عليها ورق ترشيح مبلل بمحلول